import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("Upload vendor documents", () => {
  test("Upload a document", { tag: "@DOC-01" }, async ({ apiAs }) => {
    // Background: signed in as member, vendor in draft
    const member = await apiAs("member");
    const createRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Doc Upload Vendor"),
        category: "services",
        contact_email: "billing@acme-vendor.com",
      },
    });
    expect(createRes.status(), await createRes.text()).toBe(201);
    const vendor = await createRes.json();
    expect(vendor.status, JSON.stringify(vendor)).toBe("draft");

    // When I upload "insurance_certificate.txt" as kind "insurance_certificate"
    const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: {
          name: "insurance_certificate.txt",
          mimeType: "text/plain",
          buffer: fs.readFileSync(sample("insurance_certificate.txt")),
        },
      },
    });

    // Then the response status is 201
    const uploadBody = await uploadRes.text();
    expect(uploadRes.status(), uploadBody).toBe(201);
    const document = JSON.parse(uploadBody);

    // And the document status is "processing"
    expect(document.status, uploadBody).toBe("processing");
    expect(document.vendor_id).toBe(vendor.id);
    expect(document.kind).toBe("insurance_certificate");

    // And an audit event "document.uploaded" is recorded
    await expect
      .poll(
        async () => {
          const auditRes = await member.get(`/api/vendors/${vendor.id}/audit`);
          if (auditRes.status() !== 200) return `status ${auditRes.status()}: ${await auditRes.text()}`;
          const trail = await auditRes.json();
          return trail.items.some(
            (e: { action: string; details?: { document_id?: string } }) =>
              e.action === "document.uploaded" && e.details?.document_id === document.id,
          );
        },
        { message: "audit trail should contain document.uploaded for the uploaded document" },
      )
      .toBe(true);
  });
});
